package org.strongswan.android.rookstride;
import android.content.*;import android.view.*;import androidx.test.core.app.ActivityScenario;import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;import org.junit.*;import org.junit.runner.RunWith;import org.json.*;import org.strongswan.android.ui.RookstrideActivity;import java.lang.reflect.*;import java.util.*;
import static org.junit.Assert.*;import static org.hamcrest.Matchers.*;import static androidx.test.espresso.Espresso.*;import static androidx.test.espresso.action.ViewActions.*;import static androidx.test.espresso.assertion.ViewAssertions.*;import static androidx.test.espresso.matcher.ViewMatchers.*;
/** Documentation-only server records; no SSH or VPN is submitted. */
@RunWith(AndroidJUnit4.class) public class ModulesUiTest {
 Context c;Gateway awg;ArrayList<Gateway> old;Vault vault;
 static Object invoke(Object a,String name,Class<?>[] types,Object... args)throws Exception{Method m=a.getClass().getDeclaredMethod(name,types);m.setAccessible(true);return m.invoke(a,args);}
 static void set(Object a,String name,Object value)throws Exception{Field f=a.getClass().getDeclaredField(name);f.setAccessible(true);f.set(a,value);}
 @Before public void setup()throws Exception{c=InstrumentationRegistry.getInstrumentation().getTargetContext();vault=new Vault(c);old=vault.read();awg=new Gateway();awg.set("host","vpn.example.net");awg.set("protocol","awg");awg.set("name","Module fixture");awg.set("serverName","Module fixture");awg.sshPassword="documentation-only";awg.data.put("remember",true);awg.data.put("checkedAt",System.currentTimeMillis());awg.data.put("snapshot",new JSONObject().put("services",new JSONObject().put("protocol",true)).put("filtering",new JSONObject().put("installed",true).put("running",true)).put("monitoring_available",true).put("recent_peers",1).put("connections",new JSONArray().put(new JSONObject().put("user","laptop").put("recent",true).put("upload",1024).put("download",4096))));vault.write(new ArrayList<>(Arrays.asList(awg)));c.getSharedPreferences("rookstride-ui",0).edit().remove("activityHistory").remove("activityUnread").remove("activityCompletion").putBoolean("rememberServerAccess",true).commit();c.getSharedPreferences("rookstride-deployment",0).edit().remove("progress").commit();new java.io.File(c.getNoBackupFilesDir(),"app-routing.json").delete();}
 @After public void cleanup()throws Exception{vault.write(old);new java.io.File(c.getNoBackupFilesDir(),"app-routing.json").delete();}
 void open(ActivityScenario<RookstrideActivity> screen,String page){screen.onActivity(a->{try{set(a,"selected",awg);invoke(a,"openScreen",new Class<?>[]{String.class},page);}catch(Exception e){throw new AssertionError(e);}});}
 @Test public void nativeModulesVisibleWithoutActiveVpn()throws Exception{try(ActivityScenario<RookstrideActivity> screen=ActivityScenario.launch(RookstrideActivity.class)){open(screen,"VPN");onView(withText("Ad blocking")).perform(scrollTo()).check(matches(isDisplayed()));onView(withText("Usage")).perform(scrollTo(),click());onView(withText("1 active recently")).check(matches(isDisplayed()));onView(withText("laptop")).perform(scrollTo()).check(matches(isDisplayed()));ScreenshotProof.save(c,"awg-statistics");}}
 @Test public void allTenInstalledMethodsExposeTheSameToolsWithoutActiveVpn()throws Exception{try(ActivityScenario<RookstrideActivity> screen=ActivityScenario.launch(RookstrideActivity.class)){for(SingleProtocols protocol:SingleProtocols.values()){awg.set("protocol",protocol.id);open(screen,"VPN");for(String title:Arrays.asList("VPN users","Logs","Usage","Ad blocking"))onView(withText(title)).perform(scrollTo()).check(matches(isDisplayed()));}}}
 @Test public void openVpnStatisticsExplainActiveSessionsAndUsersUseTheSameScope()throws Exception{awg.set("protocol","openvpn");JSONObject status=awg.data.getJSONObject("snapshot");status.put("statistics_kind","sessions").put("statistics_scope","active-sessions").put("users",new JSONArray().put(new JSONObject().put("login","laptop")));status.getJSONArray("connections").getJSONObject(0).put("sessions",1);try(ActivityScenario<RookstrideActivity> screen=ActivityScenario.launch(RookstrideActivity.class)){open(screen,"Sessions");onView(withText("1 users active now")).check(matches(isDisplayed()));onView(withText("Traffic covers active connections and starts again when they reconnect. Shared profiles count as one user.")).perform(scrollTo()).check(matches(isDisplayed()));open(screen,"People");onView(withText("1 active sessions")).perform(scrollTo()).check(matches(isDisplayed()));onView(withText(containsString("active connections"))).perform(scrollTo()).check(matches(isDisplayed()));onView(withText("Recent handshake")).check(doesNotExist());}}
 @Test public void updatesExpireAndRemainInActivity()throws Exception{try(ActivityScenario<RookstrideActivity> screen=ActivityScenario.launch(RookstrideActivity.class)){screen.onActivity(a->{try{invoke(a,"recordActivity",new Class<?>[]{String.class,Gateway.class},"Server refreshed",awg);set(a,"message","Server refreshed");invoke(a,"render",new Class<?>[]{});}catch(Exception e){throw new AssertionError(e);}});Thread.sleep(4600);onView(withText("Server refreshed")).check(matches(not(isDisplayed())));onView(withContentDescription("Activity, new updates")).perform(click());onView(withText("Server refreshed")).check(matches(isDisplayed()));screen.recreate();onView(withText("Server refreshed")).check(matches(isDisplayed()));ScreenshotProof.save(c,"activity-history");}}
 @Test public void forgettingAccessNeedsAcknowledgementAndPreservesVpnRecord()throws Exception{try(ActivityScenario<RookstrideActivity> screen=ActivityScenario.launch(RookstrideActivity.class)){onView(withContentDescription("App settings")).perform(click());onView(withText("Save server access on this phone")).perform(scrollTo(),click());onView(withText("Continue")).check(matches(not(isEnabled())));onView(withText("Keep saved")).perform(click());onView(withText("Save server access on this phone")).perform(scrollTo()).check(matches(isChecked())).perform(click());onView(withText("I understand I will need to sign in again.")).perform(scrollTo(),click());onView(withText("Continue")).perform(click());ArrayList<Gateway> nodes=vault.read();assertEquals(1,nodes.size());assertEquals("awg",nodes.get(0).get("protocol"));assertTrue(nodes.get(0).sshPassword.isEmpty());assertFalse(nodes.get(0).remember());}}
 @Test public void routingModesSaveAndSurviveRecreation()throws Exception{try(ActivityScenario<RookstrideActivity> screen=ActivityScenario.launch(RookstrideActivity.class)){open(screen,"Routing");onView(withText("Only selected apps")).perform(click());onView(withTagValue(is((Object)"choose-apps"))).perform(scrollTo(),click());onView(withContentDescription("Search apps")).perform(typeText("settings"),androidx.test.espresso.action.ViewActions.closeSoftKeyboard());onView(withContentDescription("Route app com.android.settings")).perform(click());onView(withText("Done")).perform(click());onView(withText("Save")).perform(scrollTo(),click());AppRouting.Policy p=AppRouting.read(c);assertEquals("only",p.mode);assertTrue(p.packages.contains("com.android.settings"));screen.recreate();onView(withText("Only selected apps")).check(matches(isChecked()));onView(withText("All except selected apps")).perform(scrollTo(),click());onView(withText("Save")).perform(scrollTo(),click());assertEquals("exclude",AppRouting.read(c).mode);onView(withText("All apps")).perform(scrollTo(),click());onView(withText("Save")).perform(scrollTo(),click());assertEquals("all",AppRouting.read(c).mode);ScreenshotProof.save(c,"app-routing");}}
 @Test public void activityCanBeClearedWithoutDeletingServer()throws Exception{try(ActivityScenario<RookstrideActivity> screen=ActivityScenario.launch(RookstrideActivity.class)){screen.onActivity(a->{try{invoke(a,"recordActivity",new Class<?>[]{String.class,Gateway.class},"VPN account created",awg);}catch(Exception e){throw new AssertionError(e);}});open(screen,"Activity");onView(withText("Clear activity")).perform(scrollTo(),click());onView(withText("Clear")).perform(click());onView(withText("No recent actions.")).check(matches(isDisplayed()));assertEquals(1,vault.read().size());}}
 @Test public void primaryTabsKeepRoutingStableAndHelpReturnsToSettings()throws Exception{
  try(ActivityScenario<RookstrideActivity> screen=ActivityScenario.launch(RookstrideActivity.class)){
   onView(withContentDescription("Split")).perform(click());onView(withText("All apps")).check(matches(isChecked()));
   final Object[] page={null};screen.onActivity(a->{try{Field f=a.getClass().getDeclaredField("pageScroll");f.setAccessible(true);page[0]=f.get(a);assertNull(a.findViewById(android.R.id.content).findViewWithTag("context-navigation"));}catch(Exception e){throw new AssertionError(e);}});
   for(int i=0;i<3;i++)onView(withContentDescription("Split")).perform(click());
   screen.onActivity(a->{try{Field f=a.getClass().getDeclaredField("pageScroll");f.setAccessible(true);assertSame(page[0],f.get(a));}catch(Exception e){throw new AssertionError(e);}});
   onView(withTagValue(is((Object)"routing-explanation"))).check(matches(withText("All apps use the VPN. Changes apply when you reconnect.")));
   onView(withText("Only selected apps")).perform(click());onView(withTagValue(is((Object)"routing-explanation"))).perform(scrollTo()).check(matches(withText(startsWith("Only the apps you choose use the VPN."))));
   onView(withText("All except selected apps")).perform(scrollTo(),click());onView(withTagValue(is((Object)"routing-explanation"))).perform(scrollTo()).check(matches(withText(startsWith("The apps you choose use your normal connection."))));ScreenshotProof.save(c,"split-tunneling-modes");
   onView(withContentDescription("App settings")).perform(click());onView(withText("Help & FAQ")).perform(scrollTo(),click());onView(withContentDescription("Back to Settings")).perform(click());onView(withText("Save server access on this phone")).perform(scrollTo()).check(matches(isDisplayed()));
   onView(withContentDescription("Servers")).perform(click());onView(withContentDescription("Manage Module fixture")).perform(scrollTo()).check(matches(isDisplayed()));
   screen.onActivity(a->{View v=a.findViewById(android.R.id.content).findViewWithTag("server-management");assertTrue("Server management uses the native icon button",v instanceof android.widget.ImageButton);assertTrue("The server settings cog must be clickable",v.isClickable());assertTrue("The server settings cog must be focusable",v.isFocusable());assertEquals("Manage Module fixture",String.valueOf(v.getContentDescription()));float density=a.getResources().getDisplayMetrics().density;assertTrue(v.getWidth()/density>=48);assertTrue(v.getHeight()/density>=48);});ScreenshotProof.save(c,"server-settings-cog");
  }
 }
 @Test public void appPickerShowsSystemIconsAndKeepsDraftSelectionsAcrossSearch()throws Exception{
  try(ActivityScenario<RookstrideActivity> screen=ActivityScenario.launch(RookstrideActivity.class)){
   onView(withContentDescription("Split")).perform(click());onView(withText("Only selected apps")).perform(click());onView(withTagValue(is((Object)"choose-apps"))).perform(scrollTo(),click());
   onView(withContentDescription("Search apps")).perform(typeText("settings"),androidx.test.espresso.action.ViewActions.closeSoftKeyboard());
   onView(withContentDescription("Route app com.android.settings")).check((v,error)->{if(error!=null)throw error;assertTrue(v instanceof android.widget.CheckedTextView);android.graphics.drawable.Drawable icon=((android.widget.CheckedTextView)v).getCompoundDrawablesRelative()[0];assertNotNull("Installed app icon missing",icon);assertTrue(icon.getBounds().width()>0);}).perform(click());
   ScreenshotProof.save(c,"app-picker-icons");onView(withContentDescription("Search apps")).perform(replaceText("no-such-installed-app"),androidx.test.espresso.action.ViewActions.closeSoftKeyboard());onView(withContentDescription("Route app com.android.settings")).check(doesNotExist());
   onView(withContentDescription("Search apps")).perform(replaceText("settings"),androidx.test.espresso.action.ViewActions.closeSoftKeyboard());onView(withContentDescription("Route app com.android.settings")).check(matches(isChecked()));onView(withText("Cancel")).perform(click());onView(withTagValue(is((Object)"choose-apps"))).check(matches(withText("Choose apps · 0 selected")));
   onView(withTagValue(is((Object)"choose-apps"))).perform(click());onView(withContentDescription("Search apps")).perform(typeText("settings"),androidx.test.espresso.action.ViewActions.closeSoftKeyboard());onView(withContentDescription("Route app com.android.settings")).perform(click());onView(withText("Done")).perform(click());onView(withText("Save")).perform(scrollTo(),click());assertEquals(new TreeSet<>(Arrays.asList("com.android.settings")),new TreeSet<>(AppRouting.read(c).packages));screen.recreate();onView(withText("Only selected apps")).check(matches(isChecked()));onView(withTagValue(is((Object)"choose-apps"))).check(matches(withText("Choose apps · 1 selected")));
  }
 }

}
